import {icon} from './assets.js';
export function emptyMenuMarkup(recordCount,areaCount){return `<section class="menu-pending" aria-labelledby="resultName"><div class="pending-mark" aria-hidden="true">${icon('bowl')}</div><div><p class="pending-label">郑州大学主校区</p><h2 id="resultName">先认准餐厅，再认真选餐。</h2><p>菜单还在逐条核实，暂时不能抽餐。你可以先查看餐厅位置与资料，也可以整理自己的饭本。</p><div class="main-actions"><a class="button primary" href="#/restaurants">查看餐厅资料${icon('arrow')}</a><a class="button secondary" href="#/mine">打开我的饭本</a></div><details><summary>为什么暂时没有菜单？</summary><p>旧版${recordCount}条记录缺少有效菜单依据，已保留为待核实。只有关联具体菜品与餐厅、且仍在有效期内的资料才进入推荐。</p></details></div></section><div class="proof-strip"><span>${areaCount} 个生活区的餐厅资料可查看</span><span>个人饭本仅保存在你的浏览器</span></div>`;}
